async function addPlan(e){e.preventDefault();const f=new FormData(e.currentTarget),months=Number(f.get("months"));if(![1,3,6,12].includes(months)){setNotice("Choose 1, 3, 6 or 12 months.");return}const{data,error}=await supabase.from("membership_plans").insert({gym_id:profile.gym_id,name:String(f.get("name")).trim(),duration_months:months,price:Number(f.get("price"))}).select().single();setNotice(error?.message||"Plan created.");if(!error){await audit("create_plan","membership_plan",data.id,{name:f.get("name"),months});setModal(null);load()}}
async function addMembership(e){e.preventDefault();const f=new FormData(e.currentTarget),months=Number(f.get("months")),start=f.get("start_date");if(![1,3,6,12].includes(months)){setNotice("Choose 1, 3, 6 or 12 months.");return}const end=new Date(start+"T00:00:00");end.setMonth(end.getMonth()+months);const{data,error}=await supabase.from("memberships").insert({gym_id:profile.gym_id,member_id:f.get("member_id"),plan_id:f.get("plan_id")||null,start_date:start,expiry_date:end.toISOString().slice(0,10),amount:Number(f.get("amount"))}).select().single();setNotice(error?.message||"Membership created.");if(!error){await audit("create_membership","membership",data.id,{member_id:f.get("member_id")});setModal(null);load()}}
async function toggleUserStatus(id,status){const next=status==="active"?"inactive":"active";const{error}=await supabase.from("profiles").update({status:next}).eq("id",id).eq("gym_id",profile.gym_id);setNotice(error?.message||"Account "+next+".");if(!error){await audit(next==="active"?"activate_account":"deactivate_account","profile",id,{status:next});load()}}
async function savePerson(e){e.preventDefault();const f=new FormData(e.currentTarget),{error}=await supabase.from("profiles").update({full_name:f.get("full_name"),phone:f.get("phone")||null}).eq("id",selected.id).eq("gym_id",profile.gym_id);setNotice(error?.message||"Member details updated.");if(!error){await audit("update_profile",selected.role,selected.id);setModal(null);setSelected(null);load()}}
