function AttendanceReport({rows,members}){const[date,setDate]=useState(today());const filtered=rows.filter(r=>r.check_in?.slice(0,10)===date);return <section className="panel"><div className="section-top"><h3>Attendance</h3><div><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><button className="secondary" onClick={()=>csvDownload("attendance-"+date+".csv",[["Person","Check in","Check out","Type"],...filtered.map(r=>[members.find(x=>x.id===r.user_id)?.full_name||r.user_id,r.check_in,r.check_out||"",r.checkout_type||""])])}>Export CSV</button></div></div><Table rows={filtered} members={members}/>{!filtered.length&&<Empty text="No attendance for this date."/>}</section>}
function Reports({payments,memberships,attendance,members,plans=[]}){const[from,setFrom]=useState(new Date(Date.now()-29*86400000).toISOString().slice(0,10)),[to,setTo]=useState(today());const inRange=d=>{const x=d?.slice(0,10);return x&&x>=from&&x<=to};const ps=payments.filter(x=>inRange(x.paid_at)),as=attendance.filter(x=>inRange(x.check_in)),ms=memberships.filter(x=>inRange(x.created_at));const total=ps.reduce((s,x)=>s+Number(x.amount),0),memberIds=new Set(members.filter(x=>x.role==="member").map(x=>x.id)),trainerIds=new Set(members.filter(x=>x.role==="trainer").map(x=>x.id)),memberAttendance=as.filter(x=>memberIds.has(x.user_id)),trainerAttendance=as.filter(x=>trainerIds.has(x.user_id)),activeMemberships=memberships.filter(x=>x.status==="active"&&x.expiry_date>=today()),expiredMemberships=memberships.filter(x=>x.status==="expired"||x.expiry_date<today()),expiresToday=memberships.filter(x=>x.status==="active"&&x.expiry_date===today()),expiresTomorrow=memberships.filter(x=>x.status==="active"&&x.expiry_date===new Date(Date.now()+86400000).toISOString().slice(0,10)),expiring=memberships.filter(x=>x.status==="active"&&x.expiry_date>=today()&&x.expiry_date<=new Date(Date.now()+7*86400000).toISOString().slice(0,10));return <><section className="cards"><Card t="Collected" n={money(total)} s={from+" to "+to}/><Card t="Pending fees" n={money(memberships.reduce((sum,m)=>sum+Math.max(0,Number(m.amount||0)-payments.filter(p=>p.membership_id===m.id).reduce((s,p)=>s+Number(p.amount||0),0)),0))} s="Current membership balance"/><Card t="Member attendance" n={memberAttendance.length} s="Records in range"/><Card t="Trainer attendance" n={trainerAttendance.length} s="Records in range"/></section><section className="panel"><div className="section-top"><h3>Reports</h3><div><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/> <input type="date" value={to} onChange={e=>setTo(e.target.value)}/> <button className="secondary" onClick={()=>csvDownload("gym-report-"+from+"-to-"+to+".csv",[["REPORT","VALUE"],["Collected",total],["Cash",ps.filter(x=>x.method==="cash").reduce((s,x)=>s+Number(x.amount),0)],["UPI",ps.filter(x=>x.method==="upi").reduce((s,x)=>s+Number(x.amount),0)],["Card",ps.filter(x=>x.method==="card").reduce((s,x)=>s+Number(x.amount),0)],["Bank transfer",ps.filter(x=>x.method==="bank_transfer").reduce((s,x)=>s+Number(x.amount),0)],["Member attendance",memberAttendance.length],["Trainer attendance",trainerAttendance.length],["Memberships created",ms.length],["Active memberships",activeMemberships.length],["Expired memberships",expiredMemberships.length],["Expiring within 7 days",expiring.length]])}>Export CSV</button></div></div><div className="cards"><Card t="Active memberships" n={activeMemberships.length} s="Current"/><Card t="Expires today" n={expiresToday.length} s="Current"/><Card t="Expires tomorrow" n={expiresTomorrow.length} s="Current"/><Card t="Expired memberships" n={expiredMemberships.length} s="Current"/><Card t="Expiring in 7 days" n={expiring.length} s="Current"/><Card t="Renewals / new memberships" n={ms.length} s={from+" to "+to}/></div><h3>Payment details</h3><PaymentTable rows={ps} members={members} memberships={memberships} plans={plans}/><h3>Attendance summary</h3><Table rows={as} members={members}/></section></>}
function UserForm({onSubmit,role}){return <form onSubmit={onSubmit} className="form"><label>Full name<input name="full_name" required/></label><label>{role==="member"?"Member":"Trainer"} ID<input name="login_id" required placeholder={role==="member"?"MEM001":"TRN001"}/></label><label>Phone<input name="phone" inputMode="tel"/></label><PasswordField name="password" label="Initial password"/><input type="hidden" name="role" value={role}/><button className="primary wide">Create {role}</button></form>}
function PeopleTable({people,onToggle,onEdit,onReset}){return <section className="panel"><div className="table"><div className="tr th"><span>Name</span><span>ID</span><span>Phone</span><span>Status</span><span>Action</span></div>{people.map(p=><div className="tr" key={p.id}><span><b>{p.full_name}</b></span><span>{p.login_id}</span><span>{p.phone||"—"}</span><span>{p.status}</span><span><button className="secondary" onClick={()=>onEdit(p)}>Edit</button> <button className="secondary" onClick={()=>onReset&&onReset(p)}>Reset password</button> <button className="secondary" onClick={()=>onToggle(p.id,p.status)}>{p.status==="active"?"Deactivate":"Activate"}</button></span></div>)}</div>{!people.length&&<Empty text="No records yet."/>}</section>}function Table({rows,members}){return <div className="table"><div className="tr th"><span>Person</span><span>Check in</span><span>Check out</span><span>Type</span></div>{rows.map(r=>{const p=members.find(x=>x.id===r.user_id);return <div className="tr" key={r.id}><span>{p?.full_name||r.user_id}</span><span>{new Date(r.check_in).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"})}</span><span>{r.check_out?new Date(r.check_out).toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit"}):"Present"}</span><span>{r.checkout_type==="system_auto"?"System Auto-Checkout":r.checkout_type||"—"}</span></div>})}</div>}function PaymentTable({rows,members,memberships=[],plans=[],gym,onEdit}){return <div className="table"><div className="tr th"><span>Receipt</span><span>Member</span><span>Amount</span><span>Method</span><span>Date</span><span></span></div>{rows.map(r=>{const membership=memberships.find(m=>m.id===r.membership_id),plan=plans.find(p=>p.id===membership?.plan_id);return <div className="tr" key={r.id}><span>{r.receipt_no}</span><span>{members.find(x=>x.id===r.member_id)?.full_name||"—"}</span><span>{money(r.amount)}</span><span>{r.method}</span><span>{fmt(r.paid_at)}</span><span><button className="secondary" onClick={()=>printReceipt(r,members.find(x=>x.id===r.member_id),gym,membership,plan)}>Receipt</button> <button className="secondary" onClick={()=>onEdit&&onEdit(r)}>Edit</button></span></div>})}</div>}
function SuperAdminApp({profile}){const[gyms,setGyms]=useState([]),[owners,setOwners]=useState([]),[modal,setModal]=useState(false),[directory,setDirectory]=useState(null),[selectedGym,setSelectedGym]=useState(null),[notice,setNotice]=useState(""),[busy,setBusy]=useState(false),[detailBusy,setDetailBusy]=useState(false),[passwordModal,setPasswordModal]=useState(null),[credential,setCredential]=useState(null),[passwordBusy,setPasswordBusy]=useState(false);
async function load(){const[g,p]=await Promise.all([supabase.from("gyms").select("*").order("created_at",{ascending:false}),supabase.from("profiles").select("id,gym_id,login_id,full_name,role,status,phone,created_at,password_change_required,password_reset_at").order("created_at",{ascending:false})]);if(g.error||p.error){setNotice(g.error?.message||p.error?.message||"Could not load platform data.");return}setGyms(g.data||[]);setOwners(p.data||[])}
useEffect(()=>{load()},[]);
function suggestId(name){const base=String(name||"").toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,8)||"GYM";return base+"01"}
async function createGym(e){e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget),{data,error}=await supabase.functions.invoke("super-admin-create-gym",{body:{name:String(f.get("gym_name")).trim(),owner_name:String(f.get("owner_name")).trim(),owner_phone:String(f.get("owner_phone")||"").trim(),login_id:String(f.get("login_id")||"").trim(),password:String(f.get("password"))}});setBusy(false);if(error||data?.error){let detail=error?.message||data?.error||"Could not create gym.";try{const body=await error?.context?.json();if(body?.error)detail=body.error}catch{}setNotice(detail);return}setNotice("Gym and Gym Owner account created successfully.");if(data?.gym){setGyms(x=>[data.gym,...x.filter(g=>g.id!==data.gym.id)])}if(data?.owner){setOwners(x=>[data.owner,...x.filter(p=>p.id!==data.owner.id)])}setModal(false);setCredential({title:"Gym owner credentials",loginId:data?.owner?.login_id,password:data?.temporary_password});load()}
const memberCount=id=>owners.filter(x=>x.gym_id===id&&x.role==="member").length,trainerCount=id=>owners.filter(x=>x.gym_id===id&&x.role==="trainer").length,owner=id=>owners.find(x=>x.gym_id===id&&x.role==="admin");
function openGym(g){setSelectedGym(g);setDirectory(null)}
async function saveDetails(){if(!selectedGym)return;setDetailBusy(true);const o=owner(selectedGym.id);const phone=String(document.getElementById("owner-phone")?.value||"").trim();const plan=String(document.getElementById("gym-plan")?.value||"").trim()||"Not assigned";const{error}=await supabase.rpc("super_admin_update_gym_details",{p_gym_id:selectedGym.id,p_phone:phone,p_platform_plan:plan});setDetailBusy(false);if(error){setNotice(error.message);return}setGyms(x=>x.map(g=>g.id===selectedGym.id?{...g,platform_plan:plan}:g));setOwners(x=>x.map(p=>p.id===o?.id?{...p,phone:phone||null}:p));setSelectedGym({...selectedGym,platform_plan:plan});setNotice("Gym details updated.");} function makeTempPassword(){const chars="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%";const bytes=new Uint32Array(14);crypto.getRandomValues(bytes);return Array.from(bytes,b=>chars[b%chars.length]).join("")}async function manageOwnerPassword(action,password){const o=owner(selectedGym?.id);if(!o)return;setPasswordBusy(true);const body={user_id:o.id,action};if(action==="reset")body.password=password;const{data,error}=await supabase.functions.invoke("super-admin-manage-owner-password",{body});setPasswordBusy(false);if(error||data?.error){setNotice(error?.message||data?.error||"Password action failed.");return}if(action==="reset"){setCredential({title:"New temporary password",loginId:o.login_id,password:data.temporary_password});setPasswordModal(null)}else setNotice("The owner will be required to change their password on next login.");load()}
return <div className="platform-shell"><header className="platform-topbar"><div className="platform-brand"><div className="platform-mark">AOG</div><div><b>ATELIER OG</b><small>GYMOS PLATFORM</small></div></div><button className="topbar-signout" onClick={signOut}>Sign out</button></header><main className="platform-main platform-content"><div className="platform-notice">{notice&&<div className={"notice "+(/could not|permission denied|failed|error/i.test(notice)?"notice-error":"")}>{notice}<button onClick={()=>setNotice("")}>×</button></div>}</div><section className="cards platform-cards"><Card t="Total gyms" n={gyms.length} s="Gyms on GymOS" onClick={()=>setDirectory("gyms")}/><Card t="Gym owners" n={owners.filter(x=>x.role==="admin").length} s="Administrator accounts" onClick={()=>setDirectory("owners")}/><Card t="Trainers" n={owners.filter(x=>x.role==="trainer").length} s="Across all gyms" onClick={()=>setDirectory("trainers")}/><Card t="Members" n={owners.filter(x=>x.role==="member").length} s="Across all gyms" onClick={()=>setDirectory("members")}/></section><section className="panel platform-panel"><div className="section-top"><div><h3>Gym accounts</h3><p className="panel-subtitle">Your onboarded gyms and their primary owners.</p></div><span className="live-pill"><i></i> Live</span></div><div className="table"><div className="tr th"><span>Gym</span><span>Owner</span><span>Login ID</span><span>Members</span><span>Trainers</span><span>Status</span></div>{gyms.map(g=>{const o=owner(g.id);return <div className="tr clickable-row" key={g.id} onClick={()=>openGym(g)}><span><b>{g.name}</b></span><span>{o?.full_name||"—"}</span><span>{o?.login_id||"—"}</span><span>{memberCount(g.id)}</span><span>{trainerCount(g.id)}</span><span>{o?.status||"—"}</span></div>})}</div>{!gyms.length&&<div className="platform-empty"><div className="empty-icon">＋</div><h4>Create your first gym</h4><p>Add a gym and its owner account to start using GymOS.</p><button className="secondary" onClick={()=>setModal(true)}>Create your first gym</button></div>}</section></main>{directory&&<Modal title={directory==="gyms"?"All gyms":directory==="owners"?"Gym owners":directory==="trainers"?"Trainers":"Members"} onClose={()=>setDirectory(null)}><div className="directory-list">{(directory==="gyms"?gyms:owners.filter(x=>x.role===(directory==="owners"?"admin":directory==="trainers"?"trainer":"member"))).map(item=>{const g=directory==="gyms"?item:gyms.find(x=>x.id===item.gym_id);const o=directory==="gyms"?owner(item.id):item;return <button className="directory-item" key={item.id} onClick={()=>directory==="gyms"?openGym(item):g&&openGym(g)}><span><b>{directory==="gyms"?item.name:o?.full_name}</b><small>{directory==="gyms"?(o?.full_name||"No owner"):((g?.name||"")+(o?.phone?" · "+o.phone:""))}</small></span><strong>›</strong></button>})}{!(directory==="gyms"?gyms:owners.filter(x=>x.role===(directory==="owners"?"admin":directory==="trainers"?"trainer":"member"))).length&&<div className="directory-empty">No records yet.</div>}</div></Modal>}{selectedGym&&<Modal title={selectedGym.name} onClose={()=>setSelectedGym(null)}><div className="detail-grid"><div><span>Owner</span><b>{owner(selectedGym.id)?.full_name||"—"}</b></div><div><span>Login ID</span><b>{owner(selectedGym.id)?.login_id||"—"}</b></div><div><span>Status</span><b>{owner(selectedGym.id)?.status||"—"}</b></div><div><span>Created</span><b>{new Date(selectedGym.created_at).toLocaleDateString()}</b></div><div><span>Password status</span><b>{owner(selectedGym.id)?.password_change_required?"Change required":"Owner-managed"}</b></div><div><span>Last reset</span><b>{owner(selectedGym.id)?.password_reset_at?new Date(owner(selectedGym.id).password_reset_at).toLocaleString("en-IN"):"—"}</b></div><label className="detail-field">Owner phone<input id="owner-phone" defaultValue={owner(selectedGym.id)?.phone||""} type="tel" placeholder="Enter phone number"/></label><label className="detail-field">GymOS plan<input id="gym-plan" defaultValue={selectedGym.platform_plan||"Not assigned"} placeholder="e.g. Standard"/></label></div><div className="detail-actions">{owner(selectedGym.id)?.phone&&<a className="secondary" href={"tel:"+owner(selectedGym.id).phone}>Call owner</a>}<button className="secondary" onClick={()=>setPasswordModal({mode:"reset"})}>Reset password</button><button className="secondary" onClick={()=>manageOwnerPassword("force_change")}>Force password change</button><button className="primary" onClick={saveDetails} disabled={detailBusy}>{detailBusy?"Saving…":"Save details"}</button></div></Modal>}{modal&&<Modal title="Create new gym" onClose={()=>setModal(false)}><form className="form" onSubmit={createGym}><label>Gym name<input name="gym_name" required placeholder="Bodyline Gym" onChange={e=>{const id=e.currentTarget.form?.elements.login_id;if(id&&!id.dataset.edited)id.value=suggestId(e.target.value)}}/></label><label>Gym Owner name<input name="owner_name" required placeholder="Owner full name"/></label><label>Owner phone<input name="owner_phone" type="tel" placeholder="10-digit mobile number"/></label><label>Owner Login ID<input name="login_id" defaultValue="GYM01" onInput={e=>e.currentTarget.dataset.edited="true"}/><small>Example: BODYLINE01. This becomes the owner's login ID.</small></label><PasswordField name="password" label="Initial password"/><button className="primary wide" disabled={busy}>{busy?"Creating…":"Create Gym + Owner"}</button></form></Modal>}{credential&&<Modal title={credential.title} onClose={()=>setCredential(null)}><div className="credential-box"><p><b>Login ID</b></p><strong>{credential.loginId}</strong><p><b>Temporary password</b></p><code>{credential.password}</code><small>Save or copy this now. GymOS does not store the readable password. The owner must change it on their next login.</small><button className="primary wide" onClick={()=>navigator.clipboard?.writeText(`Login ID: ${credential.loginId}\nTemporary password: ${credential.password}`)}>Copy credentials</button></div></Modal>}{passwordModal?.mode==="reset"&&<Modal title="Reset Gym Owner password" onClose={()=>setPasswordModal(null)}><form className="form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);manageOwnerPassword("reset",String(f.get("password")||""))}}><PasswordField name="password" label="New temporary password" placeholder="Create a temporary password"/><small>The owner will be forced to create a new private password after signing in.</small><button className="primary wide" disabled={passwordBusy}>{passwordBusy?"Resetting…":"Reset password"}</button></form></Modal>}</div>}

function PasswordChangeGate({onComplete}){const[busy,setBusy]=useState(false),[notice,setNotice]=useState("");async function submit(e){e.preventDefault();const f=new FormData(e.currentTarget),p=String(f.get("password")||""),q=String(f.get("confirm")||"");if(p!==q){setNotice("Passwords do not match.");return}if(p.length<8){setNotice("Password must be at least 8 characters.");return}setBusy(true);const{error}=await supabase.auth.updateUser({password:p});if(error){setNotice(error.message);setBusy(false);return}const{error:ce}=await supabase.functions.invoke("complete-password-change",{body:{}});if(ce){setNotice(ce.message);setBusy(false);return}setBusy(false);const next=await currentProfile();onComplete(next)}return <div className="login"><div className="login-card password-gate"><div className="platform-mark">AOG</div><h1>Change your password</h1><p>Your GymOS account was created or reset with a temporary password. Create your private password to continue.</p>{notice&&<div className="notice notice-error">{notice}</div>}<form className="form" onSubmit={submit}><PasswordField name="password" label="New password" autoFocus/><PasswordField name="confirm" label="Confirm password" placeholder="Repeat password"/><button className="primary wide" disabled={busy}>{busy?"Saving…":"Set my password"}</button></form><button className="logout" onClick={signOut}>Sign out</button></div></div>}
function App(){const[profile,setProfile]=useState(undefined);useEffect(()=>{const t=setTimeout(()=>setProfile(p=>p===undefined?null:p),5000);return()=>clearTimeout(t)},[]);useEffect(()=>{(async()=>{try{setProfile(await currentProfile())}catch{setProfile(null)}})()},[]);useEffect(()=>{if(!supabase)return;const{data}=supabase.auth.onAuthStateChange((event,session)=>{if(!session){setProfile(null);return}currentProfile().then(setProfile).catch(()=>setProfile(null))});return()=>data.subscription.unsubscribe()},[]);if(profile===undefined)return <div className="login"><div className="login-card"><h1>GYM<span>OS</span></h1><p>Loading…</p></div></div>;if(!profile)return <Login onLogin={async()=>{try{setProfile(await currentProfile())}catch{setProfile(null)}}}/>;if(profile.password_change_required)return <PasswordChangeGate onComplete={setProfile}/>;return profile.role==="super_admin"?<SuperAdminApp profile={profile}/>:profile.role==="admin"?<AdminApp profile={profile}/>:<UserPortal profile={profile}/>}class BootError extends React.Component{constructor(p){super(p);this.state={error:null}}static getDerivedStateFromError(error){return{error}}render(){if(this.state.error)return <div className="login"><div className="login-card"><h1>GYM<span>OS</span></h1><p>GymOS could not start.</p><div className="error">{String(this.state.error?.message||this.state.error).replace(/[<>]/g,"")}</div></div></div>;return this.props.children}}createRoot(document.getElementById("root")).render(<BootError><App/></BootError>);